import math
from functools import lru_cache
import sys

# Increase recursion limit for deep searches
sys.setrecursionlimit(5000)

MAX_TURNS = 50
INF = MAX_TURNS + 1

def get_moves_constrained(N):
    """Generates possible moves D (divisors and restricted multiples, D != 1)."""
    moves = set()

    # 1. Divisors (1 < d < N)
    for i in range(2, int(math.sqrt(N)) + 1):
        if N % i == 0:
            moves.add(i)
            if i * i != N:
                moves.add(N // i)

    # 2. Restricted Multiples (2*N)
    # Only the next multiple to keep the state space small for initial testing.
    moves.add(2 * N)

    return list(moves)

@lru_cache(maxsize=None)
def min_turns(N, F):
    """
    Calculates the minimum guaranteed turns to reach F from N.
    Returns INF if impossible within MAX_TURNS.
    """
    if N == F:
        return 0
    if N <= 0:
        return INF

    possible_next_turns = []

    moves = get_moves_constrained(N)

    if not moves and N != F:
        # No valid moves found
        return INF


    for D in moves:
        # Recursively find required turns from the next possible states

        # We handle the recursion depth implicitly via the cached structure and MAX_TURNS check
        try:
            turns_plus = min_turns(D + 1, F)
        except RecursionError:
            turns_plus = INF

        try:
            turns_minus = min_turns(D - 1, F)
        except RecursionError:
            turns_minus = INF

        # The organizers pick the move that maximizes the required turns for us.
        worst_case_next = max(turns_plus, turns_minus)

        if worst_case_next < INF:
            # Our turn counts 1 + the worst-case needed from the next state
            possible_next_turns.append(1 + worst_case_next)

    if not possible_next_turns:
        return INF

    # We choose the move D that minimizes the worst-case outcome
    return min(possible_next_turns)

def solve_and_record(F, S):
    """Runs the solver and formats the result."""
    # Clear cache for a new F
    min_turns.cache_clear()

    turns = min_turns(S, F)
    return turns

# --- Investigations ---

# Using S=10 as the smallest tractable starting point for initial investigation
S_values = [10] 
F_values = range(2, 8) # Investigate F from 2 up to 7

results = {}

print("--- Starting Investigation with Very Constrained Search (S=10) ---")

for F in F_values:
    print(f"\n================= Testing F = {F} =================")
    results[F] = {}
    for S in S_values:
        print(f"  Running T({F}, {S})...")
        try:
            # Start the search
            turns = solve_and_record(F, S)
            results[F][S] = turns
            print(f"  Result T({F}, {S}) = {turns}")
        except Exception as e:
            results[F][S] = f"Error: {e}"
            print(f"  Error encountered: {e}")

print("\n--- Investigation Complete ---")
print("Results Dictionary:", results)
